<script setup lang="ts">
import { computed, ref, watch, onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { useFitness, tone } from './store'
import { addDays, clone, dayOn, newDay, volume, setCount, type TrainingRecord, type FitnessItem } from '../../../shared/fitness'
import { localDate } from '../../../shared/date'
import { confirmDelete, unwrap, report } from '../lib/api'
import ItemEditor from './ItemEditor.vue'
import RecordCalendar from './RecordCalendar.vue'
import FitnessChart from './FitnessChart.vue'
import AppIcon from '../components/AppIcon.vue'
import DesignArt from './DesignArt.vue'
import ExerciseImage from './ExerciseImage.vue'
const props=defineProps<{page:string}>(),emit=defineEmits<{navigate:[page:string]}>(),fs=useFitness(),today=localDate(),route=useRoute()
const month=ref(today.slice(0,7)),selectedDate=ref(today),dateFrom=ref(month.value+'-01'),dateTo=ref(today),query=ref(''),type=ref('全部'),source=ref('全部'),pageNumber=ref(1),selectedId=ref(String(route.query.record||'')),checked=ref<string[]>([]),group=ref('按周'),metric=ref('容量'),comparePrevious=ref(false),previewRecord=ref(false),summaryOnly=ref(false),recordForm=ref<HTMLFormElement>(),imported=ref<TrainingRecord[]>([]),importError=ref(''),showDifference=ref(false),showPlan=ref(false),exportFormat=ref('csv')
const blankRecord=():TrainingRecord=>({id:crypto.randomUUID(),date:today,title:'',type:'自定义',minutes:null,notes:'',tags:'',source:'手动补录',items:[],updated:new Date().toISOString()})
const draft=ref<TrainingRecord>(blankRecord()),recordTemplate=ref(''),sourceMode=ref('空白补录'),originalItems=ref<FitnessItem[]>([])
const allRecords=computed(()=>[...fs.data.records].sort((a,b)=>b.date.localeCompare(a.date))),filtered=computed(()=>allRecords.value.filter(r=>r.date>=dateFrom.value&&r.date<=dateTo.value&&(type.value==='全部'||r.type===type.value)&&(source.value==='全部'||r.source===source.value)&&(r.title+r.notes+r.items.map(i=>fs.exercise(i.exerciseId)?.name).join(' ')).toLowerCase().includes(query.value.toLowerCase()))),monthRecords=computed(()=>allRecords.value.filter(r=>r.date.startsWith(month.value)&&(type.value==='全部'||r.type===type.value))),calendarRecords=computed(()=>monthRecords.value.filter(r=>r.date===selectedDate.value)),detail=computed(()=>allRecords.value.find(r=>r.id===selectedId.value)||(props.page==='list'?allRecords.value[0]:calendarRecords.value[0]))
watch([dateFrom,dateTo,query,type,source],()=>pageNumber.value=1)
watch(()=>props.page,p=>{if(p==='entry'&&!editingId.value){draft.value=blankRecord();summaryOnly.value=false;sourceMode.value='空白补录'}if(p!=='entry')editingId.value=''} )
const editingId=ref('')
onMounted(()=>{if(allRecords.value.length){const chosen=allRecords.value.find(r=>r.id===route.query.record)||allRecords.value[0];selectedDate.value=chosen.date;selectedId.value=chosen.id}})
watch(()=>props.page,p=>{if(p==='list'&&!selectedId.value)selectedId.value=allRecords.value[0]?.id||''})
const calendar=computed(()=>{const first=month.value+'-01',weekday=(new Date(first+'T12:00:00').getDay()+6)%7;return Array.from({length:Math.ceil((weekday+new Date(Number(month.value.slice(0,4)),Number(month.value.slice(5)),0).getDate())/7)*7},(_,i)=>addDays(first,i-weekday))})
function shiftMonth(n:number):void{const d=new Date(month.value+'-01T12:00:00');d.setMonth(d.getMonth()+n);month.value=localDate(d).slice(0,7)}
function chooseDate(d:string):void{selectedDate.value=d;selectedId.value=monthRecords.value.find(r=>r.date===d)?.id||''}
function newRecord(date=today):void{editingId.value='new';draft.value=blankRecord();draft.value.date=date;summaryOnly.value=false;sourceMode.value='空白补录';emit('navigate','entry')}
function edit(r:TrainingRecord):void{editingId.value=r.id;draft.value=clone(r);summaryOnly.value=!r.items.length;originalItems.value=clone(r.items);emit('navigate','entry')}
function copy(r:TrainingRecord):void{edit(r);draft.value.id=crypto.randomUUID();draft.value.date=today;editingId.value='new'}
async function remove(r:TrainingRecord):Promise<void>{if(await confirmDelete(r.title)){fs.data.records=fs.data.records.filter(x=>x.id!==r.id);selectedId.value='';await fs.save('记录已删除')}}
function bring(mode:string):void{sourceMode.value=mode;if(mode==='空白补录'){draft.value.items=[];return}const d=mode==='从计划带入'?dayOn(fs.data,draft.value.date):fs.data.templates.find(t=>t.id===recordTemplate.value);if(d){draft.value.title=d.title;draft.value.type=d.type;draft.value.items=clone(d.items);originalItems.value=clone(d.items)}}
async function saveRecord():Promise<void>{if(!recordForm.value?.reportValidity())return;const r=clone(draft.value);r.minutes=r.minutes==null||String(r.minutes)===''?null:Number(r.minutes);r.items=summaryOnly.value?[]:r.items;r.items.forEach(i=>i.sets.forEach(s=>(Object.keys(s) as (keyof typeof s)[]).forEach(k=>s[k]=s[k]==null||String(s[k])===''?null:Number(s[k]))));r.updated=new Date().toISOString();const index=fs.data.records.findIndex(x=>x.id===r.id);if(index<0)fs.data.records.push(r);else fs.data.records[index]=r;if(await fs.save('训练记录已保存')){selectedId.value=r.id;selectedDate.value=r.date;month.value=r.date.slice(0,7);emit('navigate','calendar')}}
const types=computed(()=>[...new Set(filtered.value.map(r=>r.type))]),totalVolume=computed(()=>volume(filtered.value.flatMap(r=>r.items))),minutes=computed(()=>filtered.value.reduce((a,r)=>a+(r.minutes||0),0)),durationCount=computed(()=>filtered.value.filter(r=>r.minutes!==null).length)
const buckets=computed(()=>{const result:{label:string;records:TrainingRecord[]}[]=[];let d=dateFrom.value;let step=group.value==='按周期'?fs.data.rhythm.length:group.value==='按月'?30:7;for(let i=0;d<=dateTo.value;i++){const next=group.value==='按月'?(()=>{const dt=new Date(d+'T12:00:00');dt.setMonth(dt.getMonth()+1);dt.setDate(1);return localDate(dt)})():addDays(d,step);result.push({label:d.slice(5).replace('-','.'),records:filtered.value.filter(r=>r.date>=d&&r.date<next)});d=next}return result})
const chartLabels=computed(()=>buckets.value.map(b=>b.label)),chartSeries=computed(()=>['推','拉','腿',...new Set(filtered.value.map(r=>r.type).filter(t=>!['推','拉','腿'].includes(t)))].filter(t=>filtered.value.some(r=>r.type===t)).map((t,i)=>({name:t,color:['#79d4b0','#aaa0ed','#ffc18e'][i],values:buckets.value.map(b=>b.records.filter(r=>r.type===t).length)}))),trend=computed(()=>buckets.value.map(b=>metric.value==='容量'?volume(b.records.flatMap(r=>r.items))/1000:metric.value==='时长'?b.records.reduce((a,r)=>a+(r.minutes||0),0):b.records.length))
const proportions=computed(()=>['推','拉','腿',...types.value.filter(t=>!['推','拉','腿'].includes(t))].filter(t=>types.value.includes(t)).map((t,i)=>({type:t,count:filtered.value.filter(r=>r.type===t).length,color:['#79d4b0','#aaa0ed','#ffc18e','#9ec5ee','#e4b0d0'][i%5]}))),donut=computed(()=>{let n=0;return 'conic-gradient('+proportions.value.map(p=>{const a=n;n+=p.count/filtered.value.length*100;return `${p.color} ${a}% ${n}%`}).join(',')+')'})
const previous=computed(()=>{const len=Math.round((Date.parse(dateTo.value)-Date.parse(dateFrom.value))/86400000)+1;return allRecords.value.filter(r=>r.date>=addDays(dateFrom.value,-len)&&r.date<dateFrom.value&&(type.value==='全部'||r.type===type.value))})
const actionId=ref(''),actionMetric=ref('最高工作重量'),aId=ref(''),bId=ref('')
const actions=computed(()=>[...new Set(filtered.value.flatMap(r=>r.items.map(i=>i.exerciseId)))].map(id=>fs.exercise(id)).filter(e=>e!==undefined)),actionHistory=computed(()=>filtered.value.filter(r=>r.items.some(i=>i.exerciseId===actionId.value&&i.sets.some(s=>{const measure=fs.exercise(actionId.value)?.measure;if(measure==='time')return s.duration!==null&&String(s.duration)!=='';if(measure==='distance')return s.distance!==null&&String(s.distance)!=='';return actionMetric.value==='总次数'?s.reps!==null&&String(s.reps)!=='':actionMetric.value==='训练容量'?s.weight!==null&&s.reps!==null&&String(s.weight)!==''&&String(s.reps)!=='':s.weight!==null&&String(s.weight)!==''}))).sort((a,b)=>a.date.localeCompare(b.date))),actionItems=(r:TrainingRecord)=>r.items.filter(i=>i.exerciseId===actionId.value),maxWeight=(r:TrainingRecord)=>fs.exercise(actionId.value)?.measure==='time'?actionItems(r).reduce((a,i)=>a+i.sets.reduce((n,s)=>n+(s.duration||0),0),0):fs.exercise(actionId.value)?.measure==='distance'?actionItems(r).reduce((a,i)=>a+i.sets.reduce((n,s)=>n+(s.distance||0),0),0):Math.max(0,...actionItems(r).flatMap(i=>i.sets.map(s=>s.weight||0))),reps=(r:TrainingRecord)=>actionItems(r).reduce((a,i)=>a+i.sets.reduce((a,s)=>a+(s.reps||0),0),0)
const actionUnit=computed(()=>fs.exercise(actionId.value)?.measure==='time'?'秒':fs.exercise(actionId.value)?.measure==='distance'?'米':'kg'),actionOptions=computed(()=>actionUnit.value==='kg'?['最高工作重量','总次数','训练容量']:[actionUnit.value==='秒'?'总时长':'总距离'])
watch(actionId,()=>{actionMetric.value=actionOptions.value[0]})
const actionValues=computed(()=>actionHistory.value.map(r=>actionMetric.value==='最高工作重量'||actionMetric.value==='总时长'||actionMetric.value==='总距离'?maxWeight(r):actionMetric.value==='总次数'?reps(r):volume(actionItems(r)))),actionA=computed(()=>actionHistory.value.find(r=>r.id===aId.value)||actionHistory.value[0]),actionB=computed(()=>actionHistory.value.find(r=>r.id===bId.value)||actionHistory.value.at(-1))
watch(actions,a=>{if(!a.some(e=>e.id===actionId.value))actionId.value=a[0]?.id||''},{immediate:true})
function download(content:string,name:string,_mime:string):void{void window.workbench.fitness.exportFile(name,content).then(result=>{if(unwrap(result))ElMessage.success('已导出')}).catch(report)}
const csvCell=(s:unknown)=>'"'+String(s??'').replace(/"/g,'""')+'"'
function exportRecords(template=false):void{if(props.page==='compare'&&!template){download('\ufeff'+[['日期','动作','记录值', '单位','总次数','组数','容量kg'],...actionHistory.value.map(r=>[r.date,fs.exercise(actionId.value)?.name,maxWeight(r),actionUnit.value,reps(r),setCount(actionItems(r)),volume(actionItems(r))])].map(row=>row.map(csvCell).join(',')).join('\r\n'),'动作对比.csv','text/csv;charset=utf-8');return}if(template){download('\ufeff日期,训练名称,类型,分钟,备注,动作明细JSON\r\n2026-10-29,背部训练,拉,55,示例（导入前删除此行）,[]','训练记录导入常用训练内容.csv','text/csv;charset=utf-8');return}const rows=checked.value.length?filtered.value.filter(r=>checked.value.includes(r.id)):filtered.value;if(exportFormat.value==='json'){download(JSON.stringify(rows,null,2),'训练记录.json','application/json');return}download('\ufeff'+[['日期','训练名称','类型','分钟','备注','动作明细JSON'],...rows.map(r=>[r.date,r.title,r.type,r.minutes,r.notes,JSON.stringify(r.items)])].map(row=>row.map(csvCell).join(',')).join('\r\n'),'训练记录.csv','text/csv;charset=utf-8')}
function parseCSV(text:string):string[][]{const rows:string[][]=[];let row:string[]=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(Boolean))rows.push(row);return rows}
async function importFile(event:Event):Promise<void>{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;importError.value='';try{const text=(await file.text()).replace(/^\uFEFF/,'');let records:TrainingRecord[];if(file.name.toLowerCase().endsWith('.json'))records=JSON.parse(text);else{const [header,...rows]=parseCSV(text);if(!header.includes('日期')||!header.includes('训练名称'))throw new Error('CSV需要“日期”和“训练名称”列，可下载模板。');records=rows.map(row=>{const value=(key:string)=>row[header.indexOf(key)]||'';return {...blankRecord(),date:value('日期'),title:value('训练名称'),type:value('类型')||'自定义',minutes:value('分钟')?Number(value('分钟')):null,notes:value('备注'),items:value('动作明细JSON')?JSON.parse(value('动作明细JSON')):[]}})}if(!Array.isArray(records))throw new Error('请选择记录数组格式的JSON。');for(const r of records){if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!r.title?.trim()||!Array.isArray(r.items))throw new Error('记录需要有效日期、训练名称和动作明细数组。');for(const item of r.items)if(!fs.exercise(item.exerciseId))throw new Error('动作库找不到动作 '+item.exerciseId+'，请先创建对应动作。')}imported.value=records.map(r=>({...blankRecord(),...r,id:crypto.randomUUID(),source:'导入'}))}catch(e){importError.value=(e as Error).message;imported.value=[]}(event.target as HTMLInputElement).value=''}
async function commitImport():Promise<void>{fs.data.records.push(...imported.value);if(await fs.save('记录已导入'))imported.value=[]}
function exportChart(event?:Event):void{const original=event?(event.currentTarget as HTMLElement).closest('.fit-card')!.querySelector('svg')!:document.querySelector('.fit-volume-card svg')!;const svg=original.cloneNode(true) as SVGElement;const children=[original,...original.querySelectorAll('*')],copies=[svg,...svg.querySelectorAll('*')];children.forEach((e,i)=>{const style=getComputedStyle(e);if(e.tagName==='text')copies[i].setAttribute('fill',style.fill);if(e.tagName==='line')copies[i].setAttribute('stroke',style.stroke)});svg.setAttribute('xmlns','http://www.w3.org/2000/svg');download(new XMLSerializer().serializeToString(svg),'训练趋势.svg','image/svg+xml')}
function preset(value:string):void{dateTo.value=today;dateFrom.value=value==='month'?today.slice(0,7)+'-01':addDays(today,-29)}
defineExpose({newRecord,importFile,exportRecords,saveRecord,exportChart})
</script>
<template>
 <div class="fit-records-pane">
 <template v-if="page!=='entry'">
 <div class="fit-record-toolbar" v-if="page==='stats'"><div class="fit-filter-chips"><label>日期 <el-date-picker v-model="dateFrom" type="date" format="YYYY.MM.DD" value-format="YYYY-MM-DD" :clearable="false"/> — <el-date-picker v-model="dateTo" type="date" format="YYYY.MM.DD" value-format="YYYY-MM-DD" :clearable="false"/></label><span class="fit-period-presets"><button @click="preset('30')">最近30天</button><button @click="preset('month')">本月</button></span></div></div>
 <section v-if="imported.length||importError" class="fit-card fit-import-preview"><h2>导入预览</h2><p v-if="importError" class="fit-error">{{ importError }}</p><template v-else><p>共 {{ imported.length }} 条记录，确认后保存。</p><table class="fit-table"><tbody><tr v-for="r in imported.slice(0,8)"><td>{{ r.date }}</td><td>{{ r.title }}</td><td>{{ r.items.length }}个动作</td></tr></tbody></table><div class="fit-actions"><button class="fit-primary" @click="commitImport">确认导入</button><button class="fit-button" @click="imported=[]">取消</button></div></template></section>
 </template>
 <RecordCalendar v-if="page==='calendar'" :initial-id="selectedId" :initial-date="selectedDate" @edit="edit" @create="newRecord"/>
 <details v-if="['calendar','list','stats'].includes(page)" class="embedded-data-management"><summary>数据管理</summary><div class="fit-actions"><label class="fit-button fit-upload">导入记录<input type="file" accept=".csv,.json" @change="importFile"/></label><button class="fit-button" @click="exportRecords()">导出记录</button></div></details>
 <template v-if="page==='stats'"><div class="fit-kpis embedded-kpis"><section class="fit-card"><small>已记录训练</small><strong>{{ filtered.length }}<small> 次</small></strong><p>只统计实际补录</p></section><section class="fit-card"><small>累计训练时间</small><strong>{{ Math.floor(minutes/60) }}<small> 小时 {{ minutes%60 }} 分钟</small></strong><p>仅计填写用时的记录</p></section><section class="fit-card"><small>累计训练容量</small><strong>{{ (totalVolume/1000).toFixed(1) }}<small> 吨</small></strong><p>仅计填写的重量与次数</p></section><section class="fit-card"><small>有记录的天数</small><strong>{{ new Set(filtered.map(r=>r.date)).size }}<small> 天</small></strong><p>无记录不代表未训练</p></section></div><div class="embedded-trend-grid"><section class="fit-card"><header><div><h2>训练节奏</h2><p class="fit-muted">当前时段内记录了多少次训练。</p></div><select v-model="group"><option>按周</option><option>按月</option><option>按周期</option></select></header><FitnessChart :labels="chartLabels" :values="buckets.map(b=>b.records.length)" bars unit="次"/></section><section class="fit-card"><h2>训练类型</h2><p class="fit-muted">不同训练内容的记录分布。</p><div class="fit-donut-row"><div class="fit-donut" :style="{background:filtered.length?donut:'var(--line)'}"><div><strong>{{ filtered.length }}</strong><small>次训练</small></div></div><div><p v-for="p in proportions"><i :style="{background:p.color}"/>{{ p.type }} · {{ p.count }} 次</p></div></div></section></div><section class="fit-card embedded-progress"><header><div><h2>一个动作的进步</h2><p class="fit-muted">先选动作，再比较它的历次记录；不混算不同动作。</p></div><select v-model="actionId"><option v-for="e in actions" :value="e.id">{{ e.name }}</option></select></header><FitnessChart v-if="actionHistory.length" :labels="actionHistory.map(r=>r.date.slice(5))" :values="actionValues" :unit="actionMetric==='总次数'?'次':actionUnit"/><p v-else class="fit-empty">该动作还没有训练记录。</p><footer><span class="fit-muted">同一动作、同一计量方式，更容易看清变化。</span><button class="fit-button" @click="emit('navigate','compare')">选择两次记录对比</button></footer></section></template>
 <template v-if="page==='compare'"><section class="fit-card embedded-comparison"><header><div><h2>两次训练，放在一起看</h2><p class="fit-muted">选择相同动作的两次记录，比较已填写的数据。</p></div><select v-model="actionId"><option v-for="e in actions" :value="e.id">{{ e.name }}</option></select></header><div v-if="actionHistory.length" class="fit-form-grid"><label>第一次<select v-model="aId"><option value="">最早一次</option><option v-for="r in actionHistory" :value="r.id">{{ r.date }} · {{ r.title }}</option></select></label><label>第二次<select v-model="bId"><option value="">最近一次</option><option v-for="r in actionHistory" :value="r.id">{{ r.date }} · {{ r.title }}</option></select></label></div><div v-if="actionA&&actionB" class="embedded-table-wrap"><table class="fit-table"><thead><tr><th>指标</th><th>第一次 · {{ actionA.date }}</th><th>第二次 · {{ actionB.date }}</th><th>变化</th></tr></thead><tbody><tr><td>{{ actionUnit==='kg'?'最高工作重量':actionUnit==='秒'?'总时长':'总距离' }}</td><td>{{ maxWeight(actionA) }} {{ actionUnit }}</td><td>{{ maxWeight(actionB) }} {{ actionUnit }}</td><td>{{ maxWeight(actionB)-maxWeight(actionA) }} {{ actionUnit }}</td></tr><tr><td>已记录组数</td><td>{{ setCount(actionItems(actionA)) }}</td><td>{{ setCount(actionItems(actionB)) }}</td><td>{{ setCount(actionItems(actionB))-setCount(actionItems(actionA)) }}</td></tr><tr v-if="actionUnit==='kg'"><td>总次数</td><td>{{ reps(actionA) }}</td><td>{{ reps(actionB) }}</td><td>{{ reps(actionB)-reps(actionA) }}</td></tr><tr v-if="actionUnit==='kg'"><td>训练容量</td><td>{{ volume(actionItems(actionA)) }} kg</td><td>{{ volume(actionItems(actionB)) }} kg</td><td>{{ volume(actionItems(actionB))-volume(actionItems(actionA)) }} kg</td></tr></tbody></table></div><p v-else class="fit-empty">还没有包含动作明细的记录，补录后可在这里对比。</p><p class="fit-muted">同一动作、同一计量方式。没有填写的数据不参与对比。</p></section></template>
 <template v-if="page==='list'">
  <section class="fit-card fit-list-filters"><div class="fit-list-dates"><el-date-picker v-model="dateFrom" type="date" format="YYYY.MM.DD" value-format="YYYY-MM-DD" :clearable="false"/> — <el-date-picker v-model="dateTo" type="date" format="YYYY.MM.DD" value-format="YYYY-MM-DD" :clearable="false"/></div><input v-model="query" placeholder="搜索训练、动作或备注"/><select v-model="type"><option>全部</option><option v-for="t in ['推','拉','腿','有氧','自定义']">{{ t }}</option></select><span>共 {{ filtered.length }} 条记录</span><button class="fit-button" @click="query='';type='全部';source='全部'">重置</button></section><div class="fit-columns"><section class="fit-card"><table class="fit-table fit-record-list"><thead><tr><th></th><th>日期</th><th>训练内容</th><th>动作数</th><th>手填用时</th><th>来源</th><th>操作</th></tr></thead><tbody><tr v-for="r in filtered" :class="{selected:selectedId===r.id}" @click="selectedId=r.id"><td><input type="checkbox" v-model="checked" :value="r.id" @click.stop/></td><td>{{ r.date.slice(5) }}</td><td><span class="fit-badge" :class="tone(r.type)">{{ r.title }}</span></td><td>{{ r.items.length }}</td><td>{{ r.minutes===null?'—':r.minutes+'分钟' }}</td><td>{{ r.source }}</td><td><button class="fit-icon" @click.stop="edit(r)" aria-label="编辑记录">✎</button><button class="fit-icon" @click.stop="remove(r)" aria-label="删除记录">×</button></td></tr></tbody></table><p class="fit-empty" v-if="!filtered.length">暂无记录，可手动补录或导入历史数据。</p></section><aside class="fit-side-column"><section class="fit-card fit-list-detail" v-if="detail"><header><h2><AppIcon name="calendar" :size="18"/>训练记录详情</h2><small>最后修改：{{ detail.updated.slice(5,10) }}</small></header><div class="fit-list-detail-heading"><p>{{ detail.date }} <span class="fit-badge">{{ detail.source }}</span></p><h2><AppIcon name="fitness"/>{{ detail.title }}</h2><DesignArt kind="hero"/></div><div class="fit-record-metrics"><span>{{ detail.items.length }} 个<small>动作</small></span><span>{{ setCount(detail.items) }} 组<small>实际组次</small></span><span>{{ detail.minutes??'—' }} 分钟<small>手填用时</small></span></div><h3>动作明细</h3><table class="fit-table"><thead><tr><th>#</th><th>动作</th><th>实际组次</th><th>实际重量</th></tr></thead><tbody><tr v-for="(i,n) in detail.items"><td>{{ String(n+1).padStart(2,'0') }}</td><td><span class="fit-mini-action"><ExerciseImage :image="fs.exercise(i.exerciseId)?.image" :alt="fs.exercise(i.exerciseId)?.name"/>{{ fs.exercise(i.exerciseId)?.name || '已删除动作' }}</span></td><td>{{ i.sets.length }} × {{ i.sets[0]?.reps??'—' }}</td><td>{{ i.sets[0]?.weight??'—' }} kg</td></tr></tbody></table><p class="fit-note">备注　{{ detail.notes||'暂无备注' }}</p><div class="fit-actions"><button class="fit-button" @click="edit(detail)"><AppIcon name="edit" :size="15"/>编辑记录</button><button class="fit-button" @click="copy(detail)"><AppIcon name="document" :size="15"/>复制为新记录</button><button class="fit-text" @click="remove(detail)">删除</button></div></section></aside></div>
 </template>
 <form v-if="page==='entry'" ref="recordForm" @submit.prevent="saveRecord"><button type="button" class="fit-text" @click="emit('navigate','calendar')">‹ 返回训练记录</button><div class="embedded-entry-layout"><div class="fit-main-column"><section class="fit-card"><header><div><h2>基本信息</h2><p class="fit-muted">必填两项，其余按需要补充。</p></div><span class="fit-badge">实际训练</span></header><div class="fit-form-grid"><label>训练日期<input type="date" v-model="draft.date" required/></label><label>训练名称<input v-model="draft.title" placeholder="例如：背部训练" required/></label><label>用时（选填，分钟）<input v-model.number="draft.minutes" type="number" min="0" placeholder="—"/></label><label>训练分类<select v-model="draft.type"><option v-for="t in ['推','拉','腿','有氧','自定义']">{{ t }}</option></select></label></div></section><section class="fit-card"><header><div><h2>动作明细</h2><p class="fit-muted">带入一份内容，再按实际训练调整。</p></div><span class="fit-muted">{{ summaryOnly?0:draft.items.length }} 个动作</span></header><div class="fit-actions"><button type="button" class="fit-button" @click="summaryOnly=false;bring('从计划带入')">从当日计划带入</button><button type="button" class="fit-button" @click="summaryOnly=false;sourceMode='从常用训练内容带入'">从常用内容选择</button><select v-if="sourceMode==='从常用训练内容带入'" v-model="recordTemplate" @change="bring('从常用训练内容带入')"><option value="">选择常用训练内容</option><option v-for="t in fs.data.templates" :value="t.id">{{ t.title }}</option></select></div><div class="embedded-entry-brief"><span>{{ summaryOnly?'这次只保存日期、名称和备注。':'点开动作，按组补充实际重量与次数。' }}</span><label><input type="checkbox" v-model="summaryOnly"/>只记录摘要</label></div><ItemEditor v-if="!summaryOnly" :items="draft.items" actual/><div v-else class="embedded-rest"><DesignArt kind="note-character"/><h3>先记下来，也很好。</h3><p class="fit-muted">以后还可以补充动作明细。</p></div></section><section class="fit-card"><label class="fit-label">本次训练备注（选填）<textarea v-model="draft.notes" placeholder="记下今天的状态、感受或想调整的地方…"/></label><details><summary class="fit-muted">更多信息（选填）</summary><label class="fit-label">标签<input v-model="draft.tags"/></label><label class="fit-label">附加信息<textarea v-model="draft.extra"/></label></details></section></div><aside><section class="fit-card embedded-record-save"><h3>这次会记录</h3><dl><dt>日期</dt><dd>{{ draft.date.replaceAll('-','.') }}</dd><dt>训练内容</dt><dd>{{ draft.title||'待填写' }}</dd><dt>动作与组数</dt><dd>{{ summaryOnly?0:draft.items.length }} 个动作 · {{ summaryOnly?0:setCount(draft.items) }} 组</dd><dt>用时</dt><dd>{{ draft.minutes??'—' }} 分钟</dd></dl><p class="fit-muted">只保存到训练记录，不会同步修改计划或常用训练内容。</p><button class="fit-primary">保存训练记录</button><button type="button" class="fit-text" @click="emit('navigate','calendar')">取消，返回记录</button></section></aside></div></form>
 </div>
</template>
